import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Your first server","description":"","frontmatter":{"pageId":"admins/getting-started","contentRevision":5},"headers":[],"relativePath":"en/admins/getting-started.md","filePath":"en/admins/getting-started.md"}'),n={name:"en/admins/getting-started.md"};function o(s,e,l,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="your-first-server" tabindex="-1">Your first server <a class="header-anchor" href="#your-first-server" aria-label="Permalink to &quot;Your first server&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>Choose a host with persistent storage and reachable TCP 25560. Prepare a private data directory and backups.</li><li>Install a server release or use the container. Pin the image version rather than relying on latest for reproducible recovery.</li><li>Configure TLS, personal authentication, an initial administrator and a separate strong Admin:ApiToken. Password login is disabled by default.</li><li>Start the server, check /health, then verify HTTPS /admin/ login and game login.</li><li>Create the shared world with an administrator client, configure the modpack and invite a test player.</li><li>Create a backup and restore it into a separate test directory before opening publicly.</li></ol><h2 id="launch-proof" tabindex="-1">Acceptance before inviting players <a class="header-anchor" href="#launch-proof" aria-label="Permalink to &quot;Acceptance before inviting players {#launch-proof}&quot;">​</a></h2><p>Prepare a separate DataDir, stable address, TLS and administrator. After startup, check more than /health: open the HTTPS panel, log in with the game, create the world as administrator and a test colony as an ordinary account. Save, leave normally, then reload. Test a small delivery and mailbox.</p><p>Record server/mod/collection versions, port, DataDir and recovery procedure. Create a backup and restore it to an isolated directory before inviting the group. Never test reset/recreateworld against the only world containing real players.</p><h2 id="launch-policy" tabindex="-1">What should players know beforehand? <a class="header-anchor" href="#launch-policy" aria-label="Permalink to &quot;What should players know beforehand? {#launch-policy}&quot;">​</a></h2><p>Publish address, verifiable fingerprint, supported version, authentication method, collection/DLC and raid/storage/treasury rules. Explain support contacts and safe operation-ID reporting. Never publish an API/admin secret alongside a shared server password.</p><p>Agree on maintenance and recovery: backup retention, rollback authority and how players learn that old sessions are fenced. This wiki explains mechanisms, not your community&#39;s policy.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>An accessible /health does not prove authentication or saving works. Apply a network policy before exposing /metrics and the admin panel. Creating/recreating a world is not a harmless health check.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./hosting">Hosting and startup</a></li><li><a href="./security-auth">TLS, authentication and permissions</a></li><li><a href="./backup-recovery">Backup and recovery</a></li></ul>',14)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
